<?php

namespace EasyCorp\Bundle\EasyAdminBundle\Maker;

use EasyCorp\Bundle\EasyAdminBundle\Contracts\Field\FieldInterface;
use function Symfony\Component\String\u;

/**
 * A field of the configureFields() method generated by the make:admin:crud command.
 *
 * @author Javier Eguiluz <javier.eguiluz@gmail.com>
 *
 * @internal
 */
final readonly class GuessedField
{
    private const CALL_DESCRIPTIONS = [
        '->allowMultipleChoices()' => 'multiple choices',
        '->hideOnForm()' => 'hidden on forms',
        '->hideOnIndex()' => 'hidden on index',
        '->onlyOnDetail()' => 'only on detail',
        '->onlyOnForms()' => 'only on forms',
    ];

    /**
     * @param class-string<FieldInterface> $fieldFqcn
     * @param list<string>                 $calls     the methods chained to the field constructor (e.g. '->hideOnForm()')
     * @param bool                         $suggested whether the field is selected by default
     */
    public function __construct(
        public string $property,
        public string $fieldFqcn,
        public array $calls = [],
        public bool $suggested = true,
    ) {
    }

    public function toPhp(): string
    {
        return sprintf("%s::new('%s')%s", $this->getFieldClassName(), $this->property, implode('', $this->calls));
    }

    public function describe(): string
    {
        $description = implode(', ', [
            $this->getFieldClassName(),
            ...array_map(static fn (string $call): string => self::CALL_DESCRIPTIONS[$call] ?? $call, $this->calls),
        ]);

        return $this->suggested ? $description : $description.' (not suggested)';
    }

    public function isDisplayedOnIndex(): bool
    {
        return [] === array_intersect($this->calls, ['->hideOnIndex()', '->onlyOnDetail()', '->onlyOnForms()']);
    }

    /**
     * Fields get a single hideOn*() or onlyOn*() call, so a field already
     * hidden on forms is turned into a field displayed only on the detail page.
     */
    public function hideOnIndex(): self
    {
        if (!$this->isDisplayedOnIndex()) {
            return $this;
        }

        $calls = \in_array('->hideOnForm()', $this->calls, true)
            ? array_map(static fn (string $call): string => '->hideOnForm()' === $call ? '->onlyOnDetail()' : $call, $this->calls)
            : [...$this->calls, '->hideOnIndex()'];

        return new self($this->property, $this->fieldFqcn, $calls, $this->suggested);
    }

    private function getFieldClassName(): string
    {
        return u($this->fieldFqcn)->afterLast('\\')->toString();
    }
}
